package com.nicochat;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("nicochat")
public interface NicoChatConfig extends Config
{
	@ConfigSection(name = "Sources", description = "Which messages get scrolled", position = 0)
	String sourcesSection = "sources";

	@ConfigSection(name = "Appearance", description = "How the comments look and move", position = 1)
	String appearanceSection = "appearance";

	@ConfigItem(keyName = "showPublic", name = "Public chat", description = "Scroll public chat messages", section = sourcesSection, position = 0)
	default boolean showPublic()
	{
		return true;
	}

	@ConfigItem(keyName = "showFriendsChat", name = "Friends chat", description = "Scroll friends chat messages", section = sourcesSection, position = 1)
	default boolean showFriendsChat()
	{
		return true;
	}

	@ConfigItem(keyName = "showClan", name = "Clan chat", description = "Scroll clan, guest clan and GIM chat messages", section = sourcesSection, position = 2)
	default boolean showClan()
	{
		return true;
	}

	@ConfigItem(keyName = "showClanAnnouncements", name = "Clan announcements", description = "Scroll clan announcements such as achievements, level-ups and member logins", section = sourcesSection, position = 3)
	default boolean showClanAnnouncements()
	{
		return true;
	}

	@ConfigItem(keyName = "showPrivate", name = "Private messages", description = "Scroll private messages (off by default - they'd be visible to anyone watching your screen)", section = sourcesSection, position = 4)
	default boolean showPrivate()
	{
		return false;
	}

	@ConfigItem(keyName = "showGame", name = "Game messages", description = "Scroll game messages such as 'You catch a shark.'", section = sourcesSection, position = 5)
	default boolean showGame()
	{
		return false;
	}

	@ConfigItem(keyName = "showOwn", name = "Your own messages", description = "Also scroll messages you send", section = sourcesSection, position = 6)
	default boolean showOwn()
	{
		return true;
	}

	@ConfigItem(keyName = "showSender", name = "Show sender name", description = "Prefix each comment with the sender's name", section = sourcesSection, position = 7)
	default boolean showSender()
	{
		return false;
	}

	@Range(min = 10, max = 64)
	@ConfigItem(keyName = "fontSize", name = "Font size", description = "Comment text size", section = appearanceSection, position = 0)
	default int fontSize()
	{
		return 24;
	}

	@Range(min = 50, max = 1000)
	@ConfigItem(keyName = "speed", name = "Speed (px/sec)", description = "How fast comments travel across the screen", section = appearanceSection, position = 1)
	default int speed()
	{
		return 220;
	}

	@Range(min = 10, max = 100)
	@ConfigItem(keyName = "opacity", name = "Opacity (%)", description = "Comment opacity", section = appearanceSection, position = 2)
	default int opacity()
	{
		return 90;
	}

	@Range(min = 10, max = 100)
	@ConfigItem(keyName = "areaHeight", name = "Screen area (%)", description = "How much of the screen height (from the top) comments may use", section = appearanceSection, position = 3)
	default int areaHeight()
	{
		return 60;
	}

	@ConfigItem(keyName = "randomLanes", name = "Random rows", description = "Place each comment on a random free row instead of the topmost free one", section = appearanceSection, position = 4)
	default boolean randomLanes()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(keyName = "overlapChance", name = "Overlap chance (%)", description = "Chance that a comment ignores free rows and can overlap another comment. 0 = never overlap", section = appearanceSection, position = 5)
	default int overlapChance()
	{
		return 15;
	}

	@Range(min = 0, max = 500)
	@ConfigItem(keyName = "verticalOffset", name = "Top offset (px)", description = "Gap between the top of the screen and the first row", section = appearanceSection, position = 6)
	default int verticalOffset()
	{
		return 30;
	}

	@ConfigItem(keyName = "textColor", name = "Text color", description = "Comment text color", section = appearanceSection, position = 7)
	default Color textColor()
	{
		return Color.WHITE;
	}
}

package com.nicochat;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.font.FontRenderContext;
import java.awt.font.TextAttribute;
import java.awt.font.TextLayout;
import java.text.AttributedString;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws comments sliding right-to-left across the whole game canvas.
 * Comments are assigned to horizontal "lanes" (rows); a new comment takes the
 * first lane whose previous comment has fully entered the screen, so
 * comments never overlap. If every lane is busy the comment waits briefly,
 * then is dropped, just like on NicoNico.
 */
@Singleton
public class NicoChatOverlay extends Overlay
{
	private static final int MAX_PENDING = 40;
	private static final int MAX_ACTIVE = 150;
	private static final long MAX_WAIT_NANOS = 4_000_000_000L;

	private static final class Comment
	{
		final TextLayout layout;
		final int width;
		final int lane;
		double x;

		Comment(TextLayout layout, double x, int width, int lane)
		{
			this.layout = layout;
			this.x = x;
			this.width = width;
			this.lane = lane;
		}
	}

	private static final class Pending
	{
		final String text;
		final long queuedAt = System.nanoTime();
		final boolean overlap;

		Pending(String text, boolean overlap)
		{
			this.text = text;
			this.overlap = overlap;
		}
	}

	private final Client client;
	private final NicoChatConfig config;

	private final List<Comment> active = new ArrayList<>();
	private final Deque<Pending> pending = new ArrayDeque<>();
	private long lastNanos;

	private int cachedFontSize = -1;
	private Font baseFont;
	private Font fallbackFont;

	@Inject
	private NicoChatOverlay(Client client, NicoChatConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void addMessage(String text)
	{
		final int chance = config.overlapChance();
		final boolean overlap = chance > 0 && ThreadLocalRandom.current().nextInt(100) < chance;
		pending.addLast(new Pending(text, overlap));
		while (pending.size() > MAX_PENDING)
		{
			pending.removeFirst();
		}
	}

	void clear()
	{
		active.clear();
		pending.clear();
		lastNanos = 0;
	}

	/**
	 * Lays the text out character by character: the RuneScape font where it has
	 * the glyph, a general system font where it does not.
	 */
	private TextLayout buildLayout(String text, FontRenderContext frc)
	{
		final AttributedString as = new AttributedString(text);
		int i = 0;
		while (i < text.length())
		{
			final int cp = text.codePointAt(i);
			final int len = Character.charCount(cp);
			as.addAttribute(TextAttribute.FONT, baseFont.canDisplay(cp) ? baseFont : fallbackFont, i, i + len);
			i += len;
		}
		return new TextLayout(as.getIterator(), frc);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final long now = System.nanoTime();
		final double dt = lastNanos == 0 ? 0 : Math.min((now - lastNanos) / 1e9, 0.25);
		lastNanos = now;

		if (active.isEmpty() && pending.isEmpty())
		{
			return null;
		}

		final int canvasW = client.getCanvasWidth();
		final int canvasH = client.getCanvasHeight();

		if (cachedFontSize != config.fontSize())
		{
			cachedFontSize = config.fontSize();
			baseFont = FontManager.getRunescapeBoldFont().deriveFont((float) cachedFontSize);
			// Logical "Dialog" font falls back to system fonts for CJK, symbols, etc.
			fallbackFont = new Font(Font.DIALOG, Font.BOLD, 1).deriveFont((float) cachedFontSize);
		}
		g.setFont(baseFont);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		final FontMetrics fm = g.getFontMetrics();
		final FontRenderContext frc = g.getFontRenderContext();

		final int laneHeight = fm.getHeight() + 2;
		final int offsetY = config.verticalOffset();
		final int usable = (int) (canvasH * (config.areaHeight() / 100.0)) - offsetY;
		final int lanes = Math.max(1, usable / laneHeight);
		final int gap = config.fontSize();

		// Move + cull
		final double dx = config.speed() * dt;
		for (Iterator<Comment> it = active.iterator(); it.hasNext(); )
		{
			Comment c = it.next();
			c.x -= dx;
			if (c.x + c.width < 0)
			{
				it.remove();
			}
		}

		// Right edge of the last comment in each lane (0 = lane is empty)
		final double[] tails = new double[lanes];
		for (Comment c : active)
		{
			if (c.lane < lanes)
			{
				tails[c.lane] = Math.max(tails[c.lane], c.x + c.width);
			}
		}

		// Admit waiting comments into free lanes, oldest first
		for (Iterator<Pending> it = pending.iterator(); it.hasNext(); )
		{
			Pending p = it.next();
			if (now - p.queuedAt > MAX_WAIT_NANOS)
			{
				it.remove();
				continue;
			}
			if (active.size() >= MAX_ACTIVE)
			{
				break;
			}

			int lane = -1;
			if (p.overlap)
			{
				// Ignore occupancy: any row, even a busy one
				lane = ThreadLocalRandom.current().nextInt(lanes);
			}
			else
			{
				int freeCount = 0;
				for (int l = 0; l < lanes; l++)
				{
					if (tails[l] + gap <= canvasW)
					{
						freeCount++;
					}
				}
				if (freeCount > 0)
				{
					int pick = config.randomLanes() ? ThreadLocalRandom.current().nextInt(freeCount) : 0;
					for (int l = 0; l < lanes; l++)
					{
						if (tails[l] + gap <= canvasW && pick-- == 0)
						{
							lane = l;
							break;
						}
					}
				}
			}
			if (lane < 0)
			{
				break; // all lanes busy; try again next frame
			}

			TextLayout layout = buildLayout(p.text, frc);
			int width = (int) Math.ceil(layout.getAdvance());
			active.add(new Comment(layout, canvasW, width, lane));
			tails[lane] = Math.max(tails[lane], canvasW + width);
			it.remove();
		}

		// Draw
		final Composite oldComposite = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, config.opacity() / 100f));
		final Color main = config.textColor();

		for (Comment c : active)
		{
			final int x = (int) c.x;
			final int y = offsetY + c.lane * laneHeight + fm.getAscent();

			g.setColor(Color.BLACK);
			c.layout.draw(g, x + 1, y + 1);
			c.layout.draw(g, x - 1, y + 1);
			c.layout.draw(g, x + 1, y - 1);
			c.layout.draw(g, x - 1, y - 1);

			g.setColor(main);
			c.layout.draw(g, x, y);
		}

		g.setComposite(oldComposite);
		return null;
	}
}

package com.nicochat;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Nico Chat",
	description = "Scrolls chat messages across the screen like NicoNico comments",
	tags = {"chat", "niconico", "danmaku", "scroll", "overlay"}
)
public class NicoChatPlugin extends Plugin
{
	private static final int MAX_LENGTH = 150;

	@Inject
	private Client client;

	@Inject
	private NicoChatConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NicoChatOverlay overlay;

	@Provides
	NicoChatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NicoChatConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			overlay.clear();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("nicochat".equals(event.getGroup()))
		{
			// font size changes would make cached widths wrong
			overlay.clear();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final ChatMessageType type = event.getType();
		if (!isEnabled(type))
		{
			return;
		}

		String message = Text.removeTags(event.getMessage())
			.replace('\u00A0', ' ')
			.replaceAll("\\p{Cntrl}", " ")
			.trim();
		if (message.isEmpty())
		{
			return;
		}

		final String name = event.getName() == null ? "" : Text.toJagexName(Text.removeTags(event.getName()));

		if (!config.showOwn() && isOwn(type, name))
		{
			return;
		}

		if (message.length() > MAX_LENGTH)
		{
			message = message.substring(0, MAX_LENGTH - 1) + "\u2026";
		}

		if (config.showSender() && !name.isEmpty() && !isAnnouncement(type))
		{
			message = name + ": " + message;
		}

		overlay.addMessage(message);
	}

	private boolean isAnnouncement(ChatMessageType type)
	{
		return type == ChatMessageType.CLAN_MESSAGE
			|| type == ChatMessageType.CLAN_GUEST_MESSAGE
			|| type == ChatMessageType.CLAN_GIM_MESSAGE
			|| type == ChatMessageType.GAMEMESSAGE;
	}

	private boolean isOwn(ChatMessageType type, String name)
	{
		if (type == ChatMessageType.PRIVATECHATOUT)
		{
			return true;
		}
		Player local = client.getLocalPlayer();
		return local != null && local.getName() != null
			&& name.equalsIgnoreCase(Text.toJagexName(local.getName()));
	}

	private boolean isEnabled(ChatMessageType type)
	{
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
				return config.showPublic();
			case FRIENDSCHAT:
				return config.showFriendsChat();
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
				return config.showClan();
			case CLAN_MESSAGE:
			case CLAN_GUEST_MESSAGE:
			case CLAN_GIM_MESSAGE:
				return config.showClanAnnouncements();
			case PRIVATECHAT:
			case MODPRIVATECHAT:
			case PRIVATECHATOUT:
				return config.showPrivate();
			case GAMEMESSAGE:
				return config.showGame();
			default:
				return false;
		}
	}
}

package com.nicochat;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class NicoChatPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(NicoChatPlugin.class);
		RuneLite.main(args);
	}
}
